const upsertProcurementSellerResponseDraft = `-- name: UpsertProcurementSellerResponseDraft :one
INSERT INTO procurement_seller_response_drafts (
    seller_response_id, payload, version
) VALUES (
    $1, $2, 1
)
ON CONFLICT (seller_response_id) DO UPDATE
   SET payload    = EXCLUDED.payload,
       version    = procurement_seller_response_drafts.version + 1,
       updated_at = now()
 WHERE procurement_seller_response_drafts.version = $3
RETURNING seller_response_id, payload, version, created_at, updated_at
`

type UpsertProcurementSellerResponseDraftParams struct {
	SellerResponseID int64           `db:"seller_response_id" json:"seller_response_id"`
	Payload          json.RawMessage `db:"payload" json:"payload"`
	Version          int32           `db:"version" json:"version"`
}

func (q *Queries) UpsertProcurementSellerResponseDraft(ctx context.Context, arg UpsertProcurementSellerResponseDraftParams) (ProcurementSellerResponseDraft, error) {
	row := q.db.QueryRow(ctx, upsertProcurementSellerResponseDraft, arg.SellerResponseID, arg.Payload, arg.Version)
	var i ProcurementSellerResponseDraft
	err := row.Scan(
		&i.SellerResponseID,
		&i.Payload,
		&i.Version,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

